@Test
public void testAndOfOr() {
    SearchArgument sArg = SearchArgumentFactory.newBuilder().startAnd().startOr().in("f1", PredicateLeaf.Type.LONG, 1L, 6L).in("f1", PredicateLeaf.Type.LONG, 3L, 4L).end().startOr().in("f1", PredicateLeaf.Type.LONG, 1L, 6L).in("f2", PredicateLeaf.Type.STRING, "c", "e").end().end().build();
    setBatch(new Long[] { 1L, 2L, 3L, 4L, 5L, 6L }, new String[] { "a", "b", "c", "d", "e", "f" });
    BatchFilter filter = FilterUtils.createVectorFilter(sArg, schema);
    filter.accept(fc);
    assertArrayEquals(new String[] { "f1", "f2" }, filter.getColumnNames());
    validateSelected(0, 2, 5);
}

