@Test
public void testOrOfAndNative() {
    VectorFilter f = new OrFilter(new VectorFilter[] { new AndFilter(new VectorFilter[] { new LongFilters.LongIn("f1", Arrays.asList(1L, 6L), false), new StringFilters.StringIn("f2", Arrays.asList("a", "c"), false) }), new AndFilter(new VectorFilter[] { new LongFilters.LongIn("f1", Arrays.asList(3L, 4L), false), new StringFilters.StringIn("f2", Arrays.asList("c", "e"), false) }) });
    setBatch(new Long[] { 1L, 2L, 3L, 4L, 5L, 6L }, new String[] { "a", "b", "c", "d", "e", "f" });
    filter(f);
    assertEquals(2, fc.getSelectedSize());
    assertArrayEquals(new int[] { 0, 2 }, Arrays.copyOf(fc.getSelected(), fc.getSelectedSize()));
}

