@Test
public void testPluginFilterWithSArg() {
    setBatch(new Long[] { 1L, 2L, null, 4L, 5L, 6L }, new String[] { "a", "B", "c", "dE", "e", "f" });
    // Define the plugin filter
    Configuration conf = new Configuration();
    OrcConf.ALLOW_PLUGIN_FILTER.setBoolean(conf, true);
    conf.set("my.filter.name", "my_str_i_eq");
    conf.set("my.filter.col.name", "f2");
    conf.set("my.filter.col.value", "de");
    conf.set("my.filter.scope", "file://db/table1/.*");
    SearchArgument sArg = SearchArgumentFactory.newBuilder().in("f1", PredicateLeaf.Type.LONG, 2L, 4L, 6L).build();
    // Setup Options
    Reader.Options opts = new Reader.Options(conf).searchArgument(sArg, new String[] { "f1" }).allowSARGToFilter(true);
    BatchFilter f = FilterFactory.createBatchFilter(opts, schema, false, OrcFile.Version.CURRENT, false, "file://db/table1/file1", conf);
    assertTrue(f instanceof BatchFilterFactory.AndBatchFilterImpl, "Filter should be an AND Batch filter");
    assertArrayEquals(new String[] { "f1", "f2" }, f.getColumnNames());
    f.accept(fc.setBatch(batch));
    validateSelected(3);
}

