    mask = new RedactMaskFactory("", "2007 _ _ _ _ _");
    assertEquals("2007-05-18 01:23:45.0", new Timestamp(mask.maskTime(ts.getTime())).toString());
    mask = new RedactMaskFactory("", "_ 7 _ _ _ _");
    assertEquals("2017-07-18 01:23:45.0", new Timestamp(mask.maskTime(ts.getTime())).toString());
    mask = new RedactMaskFactory("", "_ _ 7 _ _ _");
    assertEquals("2017-05-07 01:23:45.0", new Timestamp(mask.maskTime(ts.getTime())).toString());
