    assertEquals("1970-01-01 00:00:00.1223", dstats.getMinimum().toString());
    assertEquals("1970-01-01 00:00:01.2354", dstats.getMaximum().toString());
    stats.merge(stats);
    assertEquals("1970-01-01 00:00:00.1223", dstats.getMinimum().toString());
    assertEquals("1970-01-01 00:00:01.2354", dstats.getMaximum().toString());
    ColumnStatisticsImpl stats2 = ColumnStatisticsImpl.create(instant);
