    for (int i = 0; i < 2048; i += 10) {
        int x = (int) in.next();
        if (i < 1024) {
            assertEquals(i, x);
        } else {
            assertEquals(256 * i, x);
        }
        if (i < 2038) {
            in.skip(9);
        }
        in.skip(0);
    }
}

