@Test
public void testForcePositionalEvolution() throws Exception {
    Configuration conf = new Configuration();
    Path oldFilePath = new Path(TestVectorOrcFile.getFileFromClasspath("orc-file-11-format.orc"));
    Reader reader = OrcFile.createReader(oldFilePath, OrcFile.readerOptions(conf).filesystem(FileSystem.getLocal(conf)));
    TypeDescription fileSchema = TypeDescription.fromString("struct<col0:boolean,col1:tinyint,col2:smallint," + "col3:int,col4:bigint,col5:float,col6:double,col7:" + "binary,col8:string,col9:struct<list:array<struct<int1:int," + "string1:string>>>,col10:array<struct<int1:int,string1:string>>," + "col11:map<string,struct<int1:int,string1:string>>,col12:timestamp," + "col13:decimal(38,10)>");
    SchemaEvolution evo = new SchemaEvolution(fileSchema, reader.getSchema(), new Reader.Options(conf).forcePositionalEvolution(true));
    assertEquals(4, RecordReaderImpl.findColumns(evo, "int1"));
    evo = new SchemaEvolution(fileSchema, reader.getSchema(), new Reader.Options(conf).forcePositionalEvolution(false));
    assertEquals(-1, RecordReaderImpl.findColumns(evo, "int1"));
    TypeDescription acidSchema = SchemaEvolution.createEventSchema(fileSchema);
    SchemaEvolution evoAcid = new SchemaEvolution(acidSchema, reader.getSchema(), new Reader.Options(conf).forcePositionalEvolution(true));
    // ahead by 6 for 1 struct + 5 for row-id
    assertEquals(6 + 4, RecordReaderImpl.findColumns(evoAcid, "int1"));
    evoAcid = new SchemaEvolution(acidSchema, reader.getSchema(), new Reader.Options(conf).forcePositionalEvolution(false));
    assertEquals(-1, RecordReaderImpl.findColumns(evoAcid, "int1"));
}

@Test
public void testMaxLengthToReader() throws Exception {
    Configuration conf = new Configuration();
    OrcProto.Type rowType = OrcProto.Type.newBuilder().setKind(OrcProto.Type.Kind.STRUCT).build();
    OrcProto.Footer footer = OrcProto.Footer.newBuilder().setHeaderLength(0).setContentLength(0).setNumberOfRows(0).setRowIndexStride(0).addTypes(rowType).build();
    OrcProto.PostScript ps = OrcProto.PostScript.newBuilder().setCompression(OrcProto.CompressionKind.NONE).setFooterLength(footer.getSerializedSize()).setMagic("ORC").addVersion(0).addVersion(11).build();
    DataOutputBuffer buffer = new DataOutputBuffer();
    footer.writeTo(buffer);
    ps.writeTo(buffer);
    buffer.write(ps.getSerializedSize());
    FileSystem fs = mock(FileSystem.class);
    FSDataInputStream file = new FSDataInputStream(new BufferInStream(buffer.getData(), buffer.getLength()));
    Path p = new Path("/dir/file.orc");
    when(fs.open(eq(p))).thenReturn(file);
    OrcFile.ReaderOptions options = OrcFile.readerOptions(conf);
    options.filesystem(fs);
    options.maxLength(buffer.getLength());
    when(fs.getFileStatus(eq(p))).thenReturn(new FileStatus(10, false, 3, 3000, 0, p));
    Reader reader = OrcFile.createReader(p, options);
    assertEquals(0, reader.getNumberOfRows());
}

