@Test
public void testPredEvalWithIntStats() throws Exception {
    PredicateLeaf pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.LONG, "x", 15L, null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createIntStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.FLOAT, "x", 15.0, null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createIntStats(10, 100), pred));
    // Stats gets converted to column type. "15" is outside of "10" and "100"
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.STRING, "x", "15", null);
    assertEquals(TruthValue.NO, evaluateInteger(createIntStats(10, 100), pred));
    // Integer stats will not be converted date because of days/seconds/millis ambiguity
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.DATE, "x", LocalDate.ofEpochDay(15), null);
    try {
        evaluateInteger(createIntStats(10, 100), pred);
        fail("evaluate should throw");
    } catch (RecordReaderImpl.SargCastException ia) {
        assertEquals("ORC SARGS could not convert from Long to DATE", ia.getMessage());
    }
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.DECIMAL, "x", new HiveDecimalWritable("15"), null);
    assertEquals(TruthValue.YES_NO, evaluateInteger(createIntStats(10, 100), pred));
    pred = createPredicateLeaf(PredicateLeaf.Operator.NULL_SAFE_EQUALS, PredicateLeaf.Type.TIMESTAMP, "x", new Timestamp(15), null);
    try {
        evaluateInteger(createIntStats(10, 100), pred);
        fail("evaluate should throw");
    } catch (RecordReaderImpl.SargCastException ia) {
        assertEquals("ORC SARGS could not convert from Long to TIMESTAMP", ia.getMessage());
    }
}

