@Test
public void testGetLocalKey() {
    HadoopShims.KeyMetadata metadata128 = memoryKeystore.getCurrentKeyVersion("key128");
    LocalKey key128 = memoryKeystore.createLocalKey(metadata128);
    // we are sure the key is the same because of the random generator.
    assertEquals("39 72 2c bb f8 b9 1a 4b 90 45 c5 e6 17 5f 10 01", stringify(key128.getEncryptedKey()));
    assertEquals("46 33 66 fd 79 57 66 9a ba 4a 28 df bf 16 f2 88", stringify(key128.getDecryptedKey().getEncoded()));
    // used online aes/cbc calculator to encrypt key
    assertEquals("AES", key128.getDecryptedKey().getAlgorithm());
    // now decrypt the key again
    Key decryptKey = memoryKeystore.decryptLocalKey(metadata128, key128.getEncryptedKey());
    assertEquals(stringify(key128.getDecryptedKey().getEncoded()), stringify(decryptKey.getEncoded()));
    HadoopShims.KeyMetadata metadata256 = memoryKeystore.getCurrentKeyVersion("key256");
    LocalKey key256 = memoryKeystore.createLocalKey(metadata256);
    // this is forced by the fixed Random in the keystore for this test
    if (InMemoryKeystore.SUPPORTS_AES_256) {
        assertEquals("ea c3 2f 7f cd 5e cc da 5c 6e 62 fc 4e 63 85 08 0f " + "7b 6c db 79 e5 51 ec 9c 9c c7 fc bd 60 ee 73", stringify(key256.getEncryptedKey()));
        // used online aes/cbc calculator to encrypt key
        assertEquals("00 b0 1c 24 d9 03 bc 02 63 87 b3 f9 65 4e e7 a8 b8" + " 58 eb a0 81 06 b3 61 cf f8 06 ba 30 d4 c5 36", stringify(key256.getDecryptedKey().getEncoded()));
    } else {
        assertEquals("ea c3 2f 7f cd 5e cc da 5c 6e 62 fc 4e 63 85 08", stringify(key256.getEncryptedKey()));
        assertEquals("6d 1c ff 55 a5 44 75 11 fb e6 8e 08 cd 2a 10 e8", stringify(key256.getDecryptedKey().getEncoded()));
    }
    assertEquals("AES", key256.getDecryptedKey().getAlgorithm());
    // now decrypt the key again
    decryptKey = memoryKeystore.decryptLocalKey(metadata256, key256.getEncryptedKey());
    assertEquals(stringify(key256.getDecryptedKey().getEncoded()), stringify(decryptKey.getEncoded()));
}

