/**
 * This will test:
 * 1. Scenario where key with smaller version then existing should not be allowed
 * 2. Test multiple versions of the key
 * 3. Test get current version
 * 4. Ensure the different versions of the key have different material.
 */
@Test
public void testMultipleVersion() throws IOException {
    assertEquals(0, memoryKeystore.getCurrentKeyVersion("key256").getVersion());
    memoryKeystore.addKey("key256", 1, EncryptionAlgorithm.AES_CTR_256, "NewSecret".getBytes(StandardCharsets.UTF_8));
    assertEquals(1, memoryKeystore.getCurrentKeyVersion("key256").getVersion());
    try {
        memoryKeystore.addKey("key256", 1, EncryptionAlgorithm.AES_CTR_256, "BadSecret".getBytes(StandardCharsets.UTF_8));
        fail("Keys with smaller version should not be added.");
    } catch (final IOException e) {
        assertTrue(e.toString().contains("equal or higher version"));
    }
    memoryKeystore.addKey("key256", 2, EncryptionAlgorithm.AES_CTR_256, "NewerSecret".getBytes(StandardCharsets.UTF_8));
    assertEquals(2, memoryKeystore.getCurrentKeyVersion("key256").getVersion());
    // make sure that all 3 versions of key256 exist and have different secrets
    Key key0 = memoryKeystore.decryptLocalKey(new HadoopShims.KeyMetadata("key256", 0, EncryptionAlgorithm.AES_CTR_256), new byte[16]);
    Key key1 = memoryKeystore.decryptLocalKey(new HadoopShims.KeyMetadata("key256", 1, EncryptionAlgorithm.AES_CTR_256), new byte[16]);
    Key key2 = memoryKeystore.decryptLocalKey(new HadoopShims.KeyMetadata("key256", 2, EncryptionAlgorithm.AES_CTR_256), new byte[16]);
    assertNotEquals(new BytesWritable(key0.getEncoded()).toString(), new BytesWritable(key1.getEncoded()).toString());
    assertNotEquals(new BytesWritable(key1.getEncoded()).toString(), new BytesWritable(key2.getEncoded()).toString());
}

