@ParameterizedTest
@MethodSource("data")
public void testSchemaEvolutionTimestamp(boolean writerProlepticGregorian, boolean readerProlepticGregorian) throws Exception {
    TypeDescription schema = TypeDescription.fromString("struct<t2i:timestamp,t2d:timestamp,t2D:timestamp,t2s:timestamp," + "i2t:bigint,d2t:decimal(18,2),D2t:double,s2t:string>");
