    assertEquals(Timestamp.valueOf("2000-03-12 15:00:00"), timestamp.asScratchTimestamp(0));
    assertEquals(new HiveDecimalWritable(HiveDecimal.create("12345678.6547456")), decs.vector[0]);
    // check the contents of row 7499
