@ParameterizedTest
@MethodSource("data")
public void testSeek(Version fileFormat) throws Exception {
    TypeDescription schema = createBigRowSchema();
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).stripeSize(200000).bufferSize(65536).rowIndexStride(1000).version(fileFormat));
    VectorizedRowBatch batch = schema.createRowBatch();
    Random rand = new Random(42);
    final int COUNT = 32768;
    long[] intValues = new long[COUNT];
    double[] doubleValues = new double[COUNT];
    String[] stringValues = new String[COUNT];
    BytesWritable[] byteValues = new BytesWritable[COUNT];
    String[] words = new String[128];
    for (int i = 0; i < words.length; ++i) {
        words[i] = Integer.toHexString(rand.nextInt());
    }
    for (int i = 0; i < COUNT / 2; ++i) {
        intValues[2 * i] = rand.nextLong();
        intValues[2 * i + 1] = intValues[2 * i];
        stringValues[2 * i] = words[rand.nextInt(words.length)];
        stringValues[2 * i + 1] = stringValues[2 * i];
    }
    for (int i = 0; i < COUNT; ++i) {
        doubleValues[i] = rand.nextDouble();
        byte[] buf = new byte[20];
        rand.nextBytes(buf);
        byteValues[i] = new BytesWritable(buf);
    }
    for (int i = 0; i < COUNT; ++i) {
        appendRandomRow(batch, intValues, doubleValues, stringValues, byteValues, words, i);
        if (batch.size == 1024) {
            writer.addRowBatch(batch);
            batch.reset();
        }
    }
    if (batch.size != 0) {
        writer.addRowBatch(batch);
    }
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).filesystem(fs));
    assertEquals(COUNT, reader.getNumberOfRows());
    RecordReader rows = reader.rows();
    // get the row index
    InStream.StreamOptions options = InStream.options();
    if (reader.getCompressionKind() != CompressionKind.NONE) {
        options.withCodec(OrcCodecPool.getCodec(reader.getCompressionKind())).withBufferSize(reader.getCompressionSize());
    }
    DataReader meta = RecordReaderUtils.createDefaultDataReader(DataReaderProperties.builder().withFileSystem(fs).withPath(testFilePath).withCompression(options).withZeroCopy(false).build());
    StripePlanner planner = new StripePlanner(schema, new ReaderEncryption(), meta, reader.getWriterVersion(), true, Integer.MAX_VALUE);
    boolean[] columns = new boolean[schema.getMaximumId() + 1];
    Arrays.fill(columns, true);
    OrcIndex index = planner.parseStripe(reader.getStripes().get(0), columns).readRowIndex(null, null);
    // check the primitive columns to make sure they have the right number of
    // items in the first row group
    for (int c = 1; c < 9; ++c) {
        OrcProto.RowIndex colIndex = index.getRowGroupIndex()[c];
        assertEquals(1000, colIndex.getEntry(0).getStatistics().getNumberOfValues());
    }
    batch = reader.getSchema().createRowBatch();
    int nextRowInBatch = -1;
    for (int i = COUNT - 1; i >= 0; --i, --nextRowInBatch) {
        // if we have consumed the previous batch read a new one
        if (nextRowInBatch < 0) {
            long base = Math.max(i - 1023, 0);
            rows.seekToRow(base);
            assertTrue(rows.nextBatch(batch), "row " + i);
            nextRowInBatch = batch.size - 1;
        }
        checkRandomRow(batch, intValues, doubleValues, stringValues, byteValues, words, i, nextRowInBatch);
    }
    rows.close();
    Iterator<StripeInformation> stripeIterator = reader.getStripes().iterator();
    long offsetOfStripe2 = 0;
    long offsetOfStripe4 = 0;
    long lastRowOfStripe2 = 0;
    for (int i = 0; i < 5; ++i) {
        StripeInformation stripe = stripeIterator.next();
        if (i < 2) {
            lastRowOfStripe2 += stripe.getNumberOfRows();
        } else if (i == 2) {
            offsetOfStripe2 = stripe.getOffset();
            lastRowOfStripe2 += stripe.getNumberOfRows() - 1;
        } else if (i == 4) {
            offsetOfStripe4 = stripe.getOffset();
        }
    }
    Arrays.fill(columns, false);
    // long colulmn
    columns[5] = true;
    // text column
    columns[9] = true;
    rows = reader.rows(reader.options().range(offsetOfStripe2, offsetOfStripe4 - offsetOfStripe2).include(columns));
    rows.seekToRow(lastRowOfStripe2);
    // we only want two rows
    batch = reader.getSchema().createRowBatch(2);
    assertTrue(rows.nextBatch(batch));
    assertEquals(1, batch.size);
    assertEquals(intValues[(int) lastRowOfStripe2], getLong(batch, 0));
    assertEquals(stringValues[(int) lastRowOfStripe2], getText(batch, 0).toString());
    assertTrue(rows.nextBatch(batch));
    assertEquals(intValues[(int) lastRowOfStripe2 + 1], getLong(batch, 0));
    assertEquals(stringValues[(int) lastRowOfStripe2 + 1], getText(batch, 0).toString());
    rows.close();
}

@ParameterizedTest
@MethodSource("data")
public void testMemoryManagement(Version fileFormat) throws Exception {
    OrcConf.ROWS_BETWEEN_CHECKS.setLong(conf, 100);
    final long POOL_SIZE = 50_000;
    TypeDescription schema = createInnerSchema();
    MemoryManagerImpl memoryMgr = new MemoryManagerImpl(POOL_SIZE);
    // set up 10 files that all request the full size.
    MemoryManager.Callback ignore = newScale -> false;
    for (int f = 0; f < 9; ++f) {
        memoryMgr.addWriter(new Path("file-" + f), POOL_SIZE, ignore);
    }
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).compress(CompressionKind.NONE).stripeSize(POOL_SIZE).bufferSize(100).rowIndexStride(0).memory(memoryMgr).version(fileFormat));
    // check to make sure it is 10%
    assertEquals(0.1, memoryMgr.getAllocationScale(), 0.001);
    VectorizedRowBatch batch = schema.createRowBatch();
    batch.size = 1;
    for (int i = 0; i < 2500; ++i) {
        ((LongColumnVector) batch.cols[0]).vector[0] = i * 300;
        ((BytesColumnVector) batch.cols[1]).setVal(0, Integer.toHexString(10 * i).getBytes(StandardCharsets.UTF_8));
        writer.addRowBatch(batch);
    }
    writer.close();
    assertEquals(0.111, memoryMgr.getAllocationScale(), 0.001);
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).filesystem(fs));
    int i = 0;
    for (StripeInformation stripe : reader.getStripes()) {
        i += 1;
        assertTrue(stripe.getDataLength() < POOL_SIZE, "stripe " + i + " is too long at " + stripe.getDataLength());
    }
    // 0.11 always uses the dictionary, so ends up with a lot more stripes
    assertEquals(fileFormat == OrcFile.Version.V_0_11 ? 25 : 3, i);
    assertEquals(2500, reader.getNumberOfRows());
}

