@MethodSource("data")
public void testPredicatePushdown(Version fileFormat) throws Exception {
    TypeDescription schema = createInnerSchema();
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).stripeSize(400000L).compress(CompressionKind.NONE).bufferSize(500).rowIndexStride(1000).version(fileFormat));
    VectorizedRowBatch batch = schema.createRowBatch();
    batch.ensureSize(3500);
    batch.size = 3500;
    for (int i = 0; i < 3500; ++i) {
        ((LongColumnVector) batch.cols[0]).vector[i] = i * 300;
        ((BytesColumnVector) batch.cols[1]).setVal(i, Integer.toHexString(10 * i).getBytes(StandardCharsets.UTF_8));
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).filesystem(fs));
    assertEquals(3500, reader.getNumberOfRows());
    SearchArgument sarg = SearchArgumentFactory.newBuilder().startAnd().startNot().lessThan("int1", PredicateLeaf.Type.LONG, 300000L).end().lessThan("int1", PredicateLeaf.Type.LONG, 600000L).end().build();
    RecordReader rows = reader.rows(reader.options().range(0L, Long.MAX_VALUE).include(new boolean[] { true, true, true }).searchArgument(sarg, new String[] { null, "int1", "string1" }));
    batch = reader.getSchema().createRowBatch(2000);
    LongColumnVector ints = (LongColumnVector) batch.cols[0];
    BytesColumnVector strs = (BytesColumnVector) batch.cols[1];
    assertEquals(1000L, rows.getRowNumber());
    assertTrue(rows.nextBatch(batch));
    assertEquals(1000, batch.size);
    for (int i = 1000; i < 2000; ++i) {
        assertEquals(300 * i, ints.vector[i - 1000]);
        assertEquals(Integer.toHexString(10 * i), strs.toString(i - 1000));
    }
    assertFalse(rows.nextBatch(batch));
    assertEquals(3500, rows.getRowNumber());
    // look through the file with no rows selected
    sarg = SearchArgumentFactory.newBuilder().startAnd().lessThan("int1", PredicateLeaf.Type.LONG, 0L).end().build();
    rows = reader.rows(reader.options().range(0L, Long.MAX_VALUE).include(new boolean[] { true, true, true }).searchArgument(sarg, new String[] { null, "int1", "string1" }));
    assertEquals(3500L, rows.getRowNumber());
    assertFalse(rows.nextBatch(batch));
    // select first 100 and last 100 rows
    sarg = SearchArgumentFactory.newBuilder().startOr().lessThan("int1", PredicateLeaf.Type.LONG, 300L * 100).startNot().lessThan("int1", PredicateLeaf.Type.LONG, 300L * 3400).end().end().build();
    rows = reader.rows(reader.options().range(0L, Long.MAX_VALUE).include(new boolean[] { true, true, true }).searchArgument(sarg, new String[] { null, "int1", "string1" }).allowSARGToFilter(false));
    assertEquals(0, rows.getRowNumber());
    assertTrue(rows.nextBatch(batch));
    assertEquals(1000, batch.size);
    assertEquals(3000, rows.getRowNumber());
    for (int i = 0; i < 1000; ++i) {
        assertEquals(300 * i, ints.vector[i]);
        assertEquals(Integer.toHexString(10 * i), strs.toString(i));
    }
    assertTrue(rows.nextBatch(batch));
    assertEquals(500, batch.size);
    assertEquals(3500, rows.getRowNumber());
    for (int i = 3000; i < 3500; ++i) {
        assertEquals(300 * i, ints.vector[i - 3000]);
        assertEquals(Integer.toHexString(10 * i), strs.toString(i - 3000));
    }
    assertFalse(rows.nextBatch(batch));
    assertEquals(3500, rows.getRowNumber());
}

