            outer.tags[r] = 1;
        } else if (r < 600) {
            outer.isNull[r] = true;
        } else if (r < 800) {
            outer.tags[r] = 1;
        } else if (r < 1000) {
            outer.isNull[r] = true;
        } else {
            outer.tags[r] = 1;
        }
        ((LongColumnVector) outer.fields[0]).vector[r] = r;
        ((LongColumnVector) outer.fields[1]).vector[r] = -r;
    }
