            assertTrue(union.isNull[r], msg);
        } else if (r < 300) {
            assertFalse(union.isNull[r], msg);
            assertEquals(0, union.tags[r], msg);
            assertEquals(r, ints.vector[r], msg);
        } else if (r < 400) {
            assertFalse(union.isNull[r], msg);
            assertEquals(1, union.tags[r], msg);
            assertEquals(-r, longs.vector[r], msg);
        } else if (r < 600) {
            assertTrue(union.isNull[r], msg);
        } else if (r < 800) {
            assertFalse(union.isNull[r], msg);
            assertEquals(1, union.tags[r], msg);
            assertEquals(-r, longs.vector[r], msg);
        } else if (r < 1000) {
            assertTrue(union.isNull[r], msg);
        } else {
            assertFalse(union.isNull[r], msg);
            assertEquals(1, union.tags[r], msg);
            assertEquals(-r, longs.vector[r], msg);
        }
    }
    assertFalse(rows.nextBatch(batch));
}

/**
 * Test lists and how they interact with the child column. In particular,
 * put nulls between back to back lists and then make some lists that
 * oper lap.
 * @throws Exception
 */
@ParameterizedTest
@MethodSource("data")
public void testLists(Version fileFormat) throws Exception {
    TypeDescription schema = TypeDescription.createStruct().addField("list", TypeDescription.createList(TypeDescription.createLong()));
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).version(fileFormat));
    VectorizedRowBatch batch = schema.createRowBatch();
    batch.size = 1024;
    ListColumnVector list = (ListColumnVector) batch.cols[0];
    list.noNulls = false;
    for (int r = 0; r < 1024; ++r) {
        if (r < 200) {
            list.isNull[r] = true;
        } else if (r < 300) {
            list.offsets[r] = r - 200;
            list.lengths[r] = 1;
        } else if (r < 400) {
            list.isNull[r] = true;
        } else if (r < 500) {
            list.offsets[r] = r - 300;
            list.lengths[r] = 1;
        } else if (r < 600) {
            list.isNull[r] = true;
        } else if (r < 700) {
            list.offsets[r] = r;
            list.lengths[r] = 2;
        } else {
            list.isNull[r] = true;
        }
        ((LongColumnVector) list.child).vector[r] = r * 10;
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf));
    RecordReader rows = reader.rows();
    batch = reader.getSchema().createRowBatch(1024);
    list = (ListColumnVector) batch.cols[0];
    rows.nextBatch(batch);
    assertEquals(1024, batch.size);
    for (int r = 0; r < 1024; ++r) {
        StringBuilder actual = new StringBuilder();
        list.stringifyValue(actual, r);
        String msg = "row " + r;
        if (r < 200) {
            assertEquals("null", actual.toString(), msg);
        } else if (r < 300) {
            assertEquals("[" + ((r - 200) * 10) + "]", actual.toString(), msg);
        } else if (r < 400) {
            assertEquals("null", actual.toString(), msg);
        } else if (r < 500) {
            assertEquals("[" + ((r - 300) * 10) + "]", actual.toString(), msg);
        } else if (r < 600) {
            assertEquals("null", actual.toString(), msg);
        } else if (r < 700) {
            assertEquals("[" + (10 * r) + ", " + (10 * (r + 1)) + "]", actual.toString(), msg);
        } else {
            assertEquals("null", actual.toString(), msg);
        }
    }
    assertFalse(rows.nextBatch(batch));
}

