@MethodSource("data")
public void testMultiStripeColumnEncryption(Version fileFormat) throws Exception {
    assumeTrue(fileFormat != OrcFile.Version.V_0_11);
    final EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_CTR_128;
    final int BATCHES = 100;
    final int SEED = 3;
    final Random random = new Random(SEED);
    TypeDescription schema = TypeDescription.fromString("struct<dec:decimal(20,4)," + "dt:date," + "time:timestamp," + "dbl:double," + "bool:boolean," + "bin:binary>");
    InMemoryKeystore allKeys = new InMemoryKeystore();
    byte[][] keys = new byte[6][];
    for (int k = 0; k < keys.length; ++k) {
        keys[k] = new byte[algorithm.keyLength()];
        random.nextBytes(keys[k]);
        allKeys.addKey("key_" + k, algorithm, keys[k]);
    }
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).setSchema(schema).version(fileFormat).stripeSize(10000).setKeyProvider(allKeys).encrypt("key_0:dec;key_1:dt;key_2:time;key_3:dbl;key_4:bool;key_5:bin"));
    // Set size to 1000 precisely so that stripes are exactly 5000 rows long.
    VectorizedRowBatch batch = schema.createRowBatch(1000);
    DecimalColumnVector dec = (DecimalColumnVector) batch.cols[0];
    LongColumnVector dt = (LongColumnVector) batch.cols[1];
    TimestampColumnVector time = (TimestampColumnVector) batch.cols[2];
    DoubleColumnVector dbl = (DoubleColumnVector) batch.cols[3];
    LongColumnVector bool = (LongColumnVector) batch.cols[4];
    BytesColumnVector bin = (BytesColumnVector) batch.cols[5];
    // Generate 100 batches of 1,000 rows each
    batch.size = 1000;
    dec.isRepeating = true;
    dt.isRepeating = true;
    time.isRepeating = true;
    dbl.isRepeating = true;
    bool.isRepeating = true;
    bin.isRepeating = true;
    for (int b = 0; b < BATCHES; ++b) {
        dec.set(0, new HiveDecimalWritable(String.format("%d.%03d", b, b)));
        dt.vector[0] = new DateWritable(new Date(96 + b, 12, 11)).getDays();
        time.set(0, Timestamp.valueOf(String.format("2014-12-14 12:00:00.%04d", b)));
        dbl.vector[0] = b + 0.5;
        bool.vector[0] = b % 2;
        bin.setVal(0, Integer.toString(b).getBytes(StandardCharsets.UTF_8));
        writer.addRowBatch(batch);
    }
    writer.close();
    // Read without any keys
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).setKeyProvider(new InMemoryKeystore()));
    checkHasData(reader.rows(), batch, BATCHES, false, false, false, false, false, false);
    // read with all of the keys
    reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).setKeyProvider(allKeys));
    checkHasData(reader.rows(), batch, BATCHES, true, true, true, true, true, true);
    // try enabling each key by itself
    for (int c = 0; c < 6; ++c) {
        InMemoryKeystore single = new InMemoryKeystore();
        single.addKey("key_" + c, algorithm, keys[c]);
        reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf).setKeyProvider(single));
        boolean[] hasData = new boolean[6];
        hasData[c] = true;
        checkHasData(reader.rows(), batch, BATCHES, hasData);
    }
}

@Test
public void testSetBytes() {
    String[] strings = { "foo", "bar", "baz", "a", "", "x1341", "Z" };
    String[] negativeStrings = { "not", "in", "the", "set", "foobar" };
    byte[][] values = getByteArrays(strings);
    byte[][] negatives = getByteArrays(negativeStrings);
    // load set
    CuckooSetBytes s = new CuckooSetBytes(strings.length);
    for (byte[] v : values) {
        s.insert(v);
    }
    // test that the values we added are there
    for (byte[] v : values) {
        assertTrue(s.lookup(v, 0, v.length));
    }
    // test that values that we know are missing are shown to be absent
    for (byte[] v : negatives) {
        assertFalse(s.lookup(v, 0, v.length));
    }
    // Test that we can search correctly using a buffer and pulling
    // a sequence of bytes out of the middle of it. In this case it
    // is the 3 letter sequence "foo".
    byte[] buf = getUTF8Bytes("thewordfooisinhere");
    assertTrue(s.lookup(buf, 7, 3));
}

