@Test
public void testWrapper() throws IOException {
    Configuration conf = new Configuration();
    Path realFilename = new Path(TestVectorOrcFile.getFileFromClasspath("orc-file-11-format.orc"));
    FileSystem local = FileSystem.getLocal(conf);
    FSDataInputStream stream = local.open(realFilename);
    long fileSize = local.getFileStatus(realFilename).getLen();
    FileSystem fs = new StreamWrapperFileSystem(stream, new Path("foo"), fileSize, conf);
    assertSame(stream, fs.open(new Path("foo")));
    TypeDescription readerSchema = TypeDescription.fromString("struct<boolean1:boolean>");
    try (Reader reader = OrcFile.createReader(new Path("foo"), OrcFile.readerOptions(conf).filesystem(fs));
        RecordReader rows = reader.rows(reader.options().schema(readerSchema))) {
        // make sure that the metadata is what we expect
        assertEquals(7500, reader.getNumberOfRows());
        assertEquals("struct<boolean1:boolean,byte1:tinyint,short1:smallint," + "int1:int,long1:bigint," + "float1:float,double1:double," + "bytes1:binary,string1:string,middle:struct<list:array<struct<" + "int1:int,string1:string>>>,list:array<struct<int1:int," + "string1:string>>,map:map<string,struct<int1:int," + "string1:string>>,ts:timestamp,decimal1:decimal(38,10)>", reader.getSchema().toString());
        // read the boolean1 column and check the data
        VectorizedRowBatch batch = readerSchema.createRowBatchV2();
        LongColumnVector boolean1 = (LongColumnVector) batch.cols[0];
        int current = 0;
        for (int r = 0; r < 7500; ++r) {
            if (current >= batch.size) {
                assertTrue(rows.nextBatch(batch), "row " + r);
                current = 0;
            }
            assertEquals(r % 2, boolean1.vector[current++], "row " + r);
        }
    }
}

