@Test
public void testRecover() throws Exception {
    TypeDescription schema = getMyRecordType();
    Writer writer = OrcFile.createWriter(testFilePath, OrcFile.writerOptions(conf).fileSystem(fs).setSchema(schema));
    Random r1 = new Random(1);
    String[] words = new String[] { "It", "was", "the", "best", "of", "times,", "it", "was", "the", "worst", "of", "times,", "it", "was", "the", "age", "of", "wisdom,", "it", "was", "the", "age", "of", "foolishness,", "it", "was", "the", "epoch", "of", "belief,", "it", "was", "the", "epoch", "of", "incredulity,", "it", "was", "the", "season", "of", "Light,", "it", "was", "the", "season", "of", "Darkness,", "it", "was", "the", "spring", "of", "hope,", "it", "was", "the", "winter", "of", "despair,", "we", "had", "everything", "before", "us,", "we", "had", "nothing", "before", "us,", "we", "were", "all", "going", "direct", "to", "Heaven,", "we", "were", "all", "going", "direct", "the", "other", "way" };
    VectorizedRowBatch batch = schema.createRowBatch(1000);
    for (int i = 0; i < 21000; ++i) {
        appendMyRecord(batch, r1.nextInt(), r1.nextLong(), words[r1.nextInt(words.length)]);
        if (batch.size == batch.getMaxSize()) {
            writer.addRowBatch(batch);
            batch.reset();
        }
    }
    if (batch.size > 0) {
        writer.addRowBatch(batch);
    }
    writer.close();
    long fileSize = fs.getFileStatus(testFilePath).getLen();
    String testFilePathStr = Path.mergePaths(workDir, Path.mergePaths(new Path(Path.SEPARATOR), testFilePath)).toUri().getPath();
    String copyTestFilePathStr = Path.mergePaths(workDir, Path.mergePaths(new Path(Path.SEPARATOR), new Path("CopyTestFileDump.testDump.orc"))).toUri().getPath();
    String testCrcFilePathStr = Path.mergePaths(workDir, Path.mergePaths(new Path(Path.SEPARATOR), new Path(".TestFileDump.testDump.orc.crc"))).toUri().getPath();
    try {
        Files.copy(Paths.get(testFilePathStr), Paths.get(copyTestFilePathStr));
        // Append write data to make it a corrupt file
        try (FileOutputStream output = new FileOutputStream(testFilePathStr, true)) {
            output.write(new byte[1024]);
            output.write(OrcFile.MAGIC.getBytes(StandardCharsets.UTF_8));
            output.write(new byte[1024]);
            output.flush();
        }
        // Clean up the crc file and append data to avoid checksum read exceptions
        Files.delete(Paths.get(testCrcFilePathStr));
        conf.setInt(RECOVER_READ_SIZE, (int) (fileSize - 2));
        FileDump.main(conf, new String[] { "--recover", "--skip-dump", testFilePath.toUri().getPath() });
        assertTrue(contentEquals(testFilePathStr, copyTestFilePathStr));
    } finally {
        Files.delete(Paths.get(copyTestFilePathStr));
    }
}

@Test
public void testJsonDump() throws Exception {
    TypeDescription schema = TypeDescription.fromString("struct<i:int,l:bigint,s:string>");
    schema.findSubtype("l").setAttribute("test1", "value1").setAttribute("test2", "value2");
    conf.set(OrcConf.ENCODING_STRATEGY.getAttribute(), "COMPRESSION");
    conf.set(OrcConf.DICTIONARY_IMPL.getAttribute(), "rbtree");
    OrcFile.WriterOptions options = OrcFile.writerOptions(conf).fileSystem(fs).setSchema(schema).stripeSize(100000).compress(CompressionKind.ZLIB).bufferSize(10000).rowIndexStride(1000).bloomFilterColumns("s");
    Writer writer = OrcFile.createWriter(testFilePath, options);
    Random r1 = new Random(1);
    String[] words = new String[] { "It", "was", "the", "best", "of", "times,", "it", "was", "the", "worst", "of", "times,", "it", "was", "the", "age", "of", "wisdom,", "it", "was", "the", "age", "of", "foolishness,", "it", "was", "the", "epoch", "of", "belief,", "it", "was", "the", "epoch", "of", "incredulity,", "it", "was", "the", "season", "of", "Light,", "it", "was", "the", "season", "of", "Darkness,", "it", "was", "the", "spring", "of", "hope,", "it", "was", "the", "winter", "of", "despair,", "we", "had", "everything", "before", "us,", "we", "had", "nothing", "before", "us,", "we", "were", "all", "going", "direct", "to", "Heaven,", "we", "were", "all", "going", "direct", "the", "other", "way" };
    VectorizedRowBatch batch = schema.createRowBatch(1000);
    for (int i = 0; i < 21000; ++i) {
        ((LongColumnVector) batch.cols[0]).vector[batch.size] = r1.nextInt();
        ((LongColumnVector) batch.cols[1]).vector[batch.size] = r1.nextLong();
        if (i % 100 == 0) {
            batch.cols[2].noNulls = false;
            batch.cols[2].isNull[batch.size] = true;
        } else {
            ((BytesColumnVector) batch.cols[2]).setVal(batch.size, words[r1.nextInt(words.length)].getBytes(StandardCharsets.UTF_8));
        }
        batch.size += 1;
        if (batch.size == batch.getMaxSize()) {
            writer.addRowBatch(batch);
            batch.reset();
        }
    }
    if (batch.size > 0) {
        writer.addRowBatch(batch);
    }
    writer.close();
    PrintStream origOut = System.out;
    String outputFilename = "orc-file-dump.json";
    FileOutputStream myOut = new FileOutputStream(workDir + File.separator + outputFilename);
    // replace stdout and run command
    System.setOut(new PrintStream(myOut, true, StandardCharsets.UTF_8.toString()));
    FileDump.main(new String[] { testFilePath.toString(), "-j", "-p", "--rowindex=3" });
    System.out.flush();
    System.setOut(origOut);
    TestFileDump.checkOutput(outputFilename, workDir + File.separator + outputFilename);
}
